import {jest} from '@jest/globals';
import {Ajv} from 'ajv';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  afterEach(() => {
    jest.restoreAllMocks();
  });

  it('rejects input omitting a required property and never reaches the executor', async () => {
    const registry = new ToolRegistry();
    let reached = false;
    registry.register(
      {
        name: 'send_alert',
        description: 'Send an alert to a channel',
        inputSchema: {type: 'object', properties: {channel: {type: 'string'}}, required: ['channel']},
      },
      async () => {
        reached = true;
        return 'sent';
      }
    );

    const response = await registry.execute('send_alert', {});

    expect({reached, rejection: response.result}).toEqual({
      reached: false,
      rejection: expect.stringMatching(/input\.channel is required/),
    });
  });

  it('passes undeclared extra properties through to the executor unchanged, calling it once', async () => {
    const registry = new ToolRegistry();
    const seen: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'find_note',
        description: 'Find a stored note by title',
        inputSchema: {
          type: 'object',
          properties: {title: {type: 'string'}},
          required: ['title'],
        },
      },
      async input => {
        seen.push(input);
        return 'note found';
      }
    );

    const response = await registry.execute('find_note', {title: 'groceries', tag: 'personal'});

    expect({seen, response}).toEqual({
      seen: [{title: 'groceries', tag: 'personal'}],
      response: {result: 'note found'},
    });
  });

  it('rejects a wrong-typed field naming the path and expected type, never the value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'search_docs',
        description: 'Search the documentation',
        inputSchema: {
          type: 'object',
          properties: {maxHits: {type: 'number'}},
          required: ['maxHits'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'no results';
      }
    );

    const response = await registry.execute('search_docs', {maxHits: 'plenty'});

    // The rejection is matched whole, so a result that echoed the offending value could not satisfy it.
    expect({executorCalls, rejection: response.result}).toEqual({
      executorCalls: 0,
      rejection: expect.stringMatching(/^input rejected: input\.maxHits must be number$/),
    });
  });

  it('throws at registration naming the tool when a static schema cannot compile', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'flag_flipper',
          description: 'Flip a named flag',
          inputSchema: {
            type: 'object',
            properties: {flag: {type: 'not-a-real-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/flag_flipper/);
  });

  it('validates a function-valued source against the schema returned for that call', async () => {
    const registry = new ToolRegistry();
    const firstSchema = {
      name: 'shape_shifter',
      description: 'Changes its schema between calls',
      inputSchema: {type: 'object', properties: {firstName: {type: 'string'}}, required: ['firstName']},
    };
    const secondSchema = {
      ...firstSchema,
      inputSchema: {type: 'object', properties: {lastName: {type: 'string'}}, required: ['lastName']},
    };
    const schemaPerResolution = [firstSchema, firstSchema, secondSchema, secondSchema];
    registry.register(() => schemaPerResolution.shift() ?? secondSchema, async () => 'ran');

    const missingFirst = await registry.execute('shape_shifter', {});
    const firstInputUnderNewSchema = await registry.execute('shape_shifter', {firstName: 'Ada'});
    const corrected = await registry.execute('shape_shifter', {lastName: 'Lovelace'});

    expect({
      missingFirst: missingFirst.result,
      rejectedByCurrentSchema: firstInputUnderNewSchema.result,
      corrected,
    }).toEqual({
      missingFirst: expect.stringMatching(/input\.firstName is required/),
      rejectedByCurrentSchema: expect.stringMatching(/input\.lastName is required/),
      corrected: {result: 'ran'},
    });
  });

  it('compiles a static tool schema once across ten execute calls', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'repeat_tool',
        description: 'Answers the same way every time',
        inputSchema: {type: 'object', properties: {n: {type: 'number'}}, required: ['n']},
      },
      async () => 'ok'
    );

    for (let call = 0; call < 10; call++) {
      await registry.execute('repeat_tool', {n: call});
    }

    expect(compile).toHaveBeenCalledTimes(1);
  });

  it('keeps throwing Unknown tool for an unregistered name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('never_registered', {})).rejects.toThrow('Unknown tool: never_registered');
  });
});

