it('feeds a schema rejection back as a tool_result so the model can correct the call', async () => {
  const rejectionSeenByProvider: string[] = [];
  const executorInputs: Array<Record<string, unknown>> = [];
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'lookup',
      description: 'looks things up',
      inputSchema: {type: 'object', properties: {query: {type: 'string'}}, required: ['query']},
    },
    async input => {
      executorInputs.push(input);
      return `found ${String(input.query)}`;
    }
  );
  let round = 0;
  const provider: AIProvider = {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      round += 1;
      if (round === 1) {
        yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {}}};
        yield STOP_FOR_TOOL;
        return;
      }
      if (round !== 2) {
        yield {type: 'text', text: 'found it'};
        yield STOP_DONE;
        return;
      }
      rejectionSeenByProvider.push(lastToolResultContent(params));
      yield {type: 'tool_use', toolCall: {id: 'call-2', name: 'lookup', input: {query: 'spec links'}}};
      yield STOP_FOR_TOOL;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);

  const reply = await orchestrator.processMessage(createSession('find the spec'));

  expect({
    reply,
    executorInputs,
